-- A2Billing 3.0 (nixonch) installation schema for MySQL 8.x.
-- A2Billing / Star2billing S.L.; GNU Affero General Public License v3 or later.
-- Original copyright and license notices are retained in ../mysql-5.x/.
-- Canonical final structure and initial data; for an EMPTY database only.
-- Re-export and validate with ../mysql-5.x/build-install.py.
-- Standard prefix names win exact matches; additional Josko prefixes are included.
-- Agent data still used by shared payments, tickets and history is retained.
SET NAMES utf8 COLLATE utf8_bin;
SET @a2b_install_sql_mode = @@SESSION.sql_mode;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

CREATE TABLE `cc_agent` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `datecreation` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `login` char(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `language` char(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT 'en',
  `commission` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `lastname` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `firstname` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `email` char(70) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `com_balance` decimal(15,5) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `login` (`login`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_agent_commission` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_payment` bigint DEFAULT NULL,
  `id_card` bigint NOT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `amount` decimal(15,5) NOT NULL,
  `description` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin,
  `id_agent` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_alarm` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `periode` int NOT NULL DEFAULT '1',
  `type` int NOT NULL DEFAULT '1',
  `maxvalue` float NOT NULL,
  `minvalue` float NOT NULL DEFAULT '-1',
  `id_trunk` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `numberofrun` int NOT NULL DEFAULT '0',
  `numberofalarm` int NOT NULL DEFAULT '0',
  `datecreate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `datelastrun` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `emailreport` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_alarm_report` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cc_alarm_id` bigint NOT NULL,
  `calculatedvalue` float NOT NULL,
  `daterun` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_autorefill_report` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `daterun` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `totalcardperform` int DEFAULT NULL,
  `totalcredit` decimal(15,5) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_backup` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `path` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `creationdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cons_cc_backup_name` (`name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_billing_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_card` bigint NOT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_invoice` bigint NOT NULL,
  `start_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_call` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sessionid` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `uniqueid` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `card_id` bigint NOT NULL,
  `card_caller` bigint NOT NULL DEFAULT '0',
  `card_called` bigint NOT NULL,
  `card_seller` bigint NOT NULL DEFAULT '0',
  `nasipaddress` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `starttime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `stoptime` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `sessiontime` int DEFAULT NULL,
  `calledstation` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `calledexten` int DEFAULT NULL,
  `sessionbill` float DEFAULT NULL,
  `margindillers` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `margindiller` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `id_tariffgroup` int DEFAULT NULL,
  `id_tariffplan` int DEFAULT NULL,
  `id_ratecard` int DEFAULT NULL,
  `id_trunk` int DEFAULT NULL,
  `sipiax` int DEFAULT '0',
  `src` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `src_peername` int DEFAULT NULL,
  `src_exten` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `id_did` int DEFAULT NULL,
  `buycost` decimal(15,5) DEFAULT '0.00000',
  `id_card_package_offer` int DEFAULT '0',
  `real_sessiontime` int DEFAULT NULL,
  `dnid` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `terminatecauseid` int DEFAULT '1',
  `destination` bigint DEFAULT '0',
  `callbackid` bigint NOT NULL DEFAULT '0',
  `faxstatus` smallint DEFAULT NULL,
  `remotefaxid` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `faxpages` smallint DEFAULT NULL,
  `faxbitrate` smallint DEFAULT NULL,
  `faxresolution` smallint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `starttime` (`starttime`),
  KEY `calledstation` (`calledstation`),
  KEY `terminatecauseid` (`terminatecauseid`),
  KEY `uniqueid` (`uniqueid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_call_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sessionid` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `uniqueid` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `card_id` bigint NOT NULL,
  `nasipaddress` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `starttime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `stoptime` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `sessiontime` int DEFAULT NULL,
  `calledstation` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `sessionbill` float DEFAULT NULL,
  `id_tariffgroup` int DEFAULT NULL,
  `id_tariffplan` int DEFAULT NULL,
  `id_ratecard` int DEFAULT NULL,
  `id_trunk` int DEFAULT NULL,
  `sipiax` int DEFAULT '0',
  `src` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `id_did` int DEFAULT NULL,
  `buycost` decimal(15,5) DEFAULT '0.00000',
  `id_card_package_offer` int DEFAULT '0',
  `real_sessiontime` int DEFAULT NULL,
  `dnid` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `terminatecauseid` int DEFAULT '1',
  `destination` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `starttime` (`starttime`),
  KEY `calledstation` (`calledstation`),
  KEY `terminatecauseid` (`terminatecauseid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_callback_spool` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `uniqueid` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `entry_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `server_ip` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `num_attempt` int NOT NULL DEFAULT '0',
  `max_attempt` int NOT NULL DEFAULT '-1',
  `last_attempt_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `manager_result` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `agi_result` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `callback_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `channel` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `exten` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `context` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `priority` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `application` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `data` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `timeout` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `callerid` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `variable` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `account` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `async` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `actionid` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `id_server` int DEFAULT NULL,
  `id_server_group` int DEFAULT NULL,
  `next_attempt_time` timestamp NULL DEFAULT NULL,
  `reason` int DEFAULT NULL,
  `num_attempts_unavailable` int NOT NULL DEFAULT '0',
  `num_attempts_busy` int NOT NULL DEFAULT '0',
  `num_attempts_noanswer` int NOT NULL DEFAULT '0',
  `exten_leg_a` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `leg_a` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `last_status` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `surveillance` int NOT NULL DEFAULT '0',
  `timeout1` smallint NOT NULL DEFAULT '0',
  `sound1` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `timeout2` smallint NOT NULL DEFAULT '0',
  `flagringup` int DEFAULT '0',
  `calleridprefix` char(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `calleridlength` smallint NOT NULL DEFAULT '13',
  `localtz` char(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cc_callback_spool_uniqueid_key` (`uniqueid`),
  KEY `status` (`status`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_callerid` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cid` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `id_cc_card` bigint NOT NULL,
  `activated` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT 't',
  `callback` int NOT NULL DEFAULT '0',
  `phonenumber` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `verify` int NOT NULL DEFAULT '0',
  `warning_threshold` int NOT NULL DEFAULT '-1',
  `say_dialednumber` smallint NOT NULL DEFAULT '0',
  `say_rateinitial` smallint NOT NULL DEFAULT '0',
  `say_timetotalk` smallint NOT NULL DEFAULT '0',
  `say_balance_after_call` smallint NOT NULL DEFAULT '0',
  `cli_replace` smallint NOT NULL DEFAULT '0',
  `cli_localreplace` smallint NOT NULL DEFAULT '0',
  `cli_otherreplace` smallint NOT NULL DEFAULT '0',
  `cli_prefixreplace` char(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `blacklist` smallint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `cons_cc_callerid_cid` (`cid`),
  KEY `id_cc_card` (`id_cc_card`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_campaign` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `creationdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `startingdate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `expirationdate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `description` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin,
  `id_card` bigint NOT NULL DEFAULT '0',
  `secondusedreal` int DEFAULT '0',
  `nb_callmade` int DEFAULT '0',
  `status` int NOT NULL DEFAULT '1',
  `frequency` int NOT NULL DEFAULT '20',
  `forward_number` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `daily_start_time` time NOT NULL DEFAULT '10:00:00',
  `daily_stop_time` time NOT NULL DEFAULT '18:00:00',
  `monday` tinyint NOT NULL DEFAULT '1',
  `tuesday` tinyint NOT NULL DEFAULT '1',
  `wednesday` tinyint NOT NULL DEFAULT '1',
  `thursday` tinyint NOT NULL DEFAULT '1',
  `friday` tinyint NOT NULL DEFAULT '1',
  `saturday` tinyint NOT NULL DEFAULT '0',
  `sunday` tinyint NOT NULL DEFAULT '0',
  `id_cid_group` int NOT NULL,
  `id_campaign_config` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cons_cc_campaign_campaign_name` (`name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_campaign_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `flatrate` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `context` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `description` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_campaign_phonebook` (
  `id_campaign` int NOT NULL,
  `id_phonebook` int NOT NULL,
  PRIMARY KEY (`id_campaign`,`id_phonebook`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_campaign_phonestatus` (
  `id_phonenumber` bigint NOT NULL,
  `id_campaign` int NOT NULL,
  `id_callback` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `status` int NOT NULL DEFAULT '0',
  `lastuse` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_phonenumber`,`id_campaign`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_campaignconf_cardgroup` (
  `id_campaign_config` int NOT NULL,
  `id_card_group` int NOT NULL,
  PRIMARY KEY (`id_campaign_config`,`id_card_group`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_card` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_diller` bigint NOT NULL DEFAULT '0',
  `margin` int NOT NULL DEFAULT '0',
  `margin_diller` int NOT NULL DEFAULT '10',
  `commission` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `creationdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `firstusedate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `expirationdate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `enableexpire` int DEFAULT '0',
  `expiredays` int DEFAULT '0',
  `username` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `useralias` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `uipass` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `credit` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `tariff` int DEFAULT '0',
  `dillertariffs` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `id_didgroup` int DEFAULT '0',
  `activated` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT 'f',
  `status` int NOT NULL DEFAULT '1',
  `lastname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `firstname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `address` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `city` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `state` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `country` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `areaprefix` smallint DEFAULT NULL,
  `citylength` smallint DEFAULT NULL,
  `removeaddprefix` char(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `addprefixinternational` char(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `zipcode` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `email` varchar(70) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `fax` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `extmin` int NOT NULL DEFAULT '701',
  `extmax` int NOT NULL DEFAULT '799',
  `extquantity` int NOT NULL DEFAULT '24',
  `inuse` int DEFAULT '0',
  `simultaccess` int DEFAULT '0',
  `currency` char(3) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT 'USD',
  `lastuse` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `nbused` int DEFAULT '0',
  `typepaid` int DEFAULT '0',
  `creditlimit` int DEFAULT '0',
  `voipcall` int DEFAULT '0',
  `sip_buddy` int DEFAULT '0',
  `iax_buddy` int DEFAULT '0',
  `language` char(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT 'en',
  `redial` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `runservice` int DEFAULT '0',
  `nbservice` int DEFAULT '0',
  `id_campaign` int DEFAULT '-1',
  `num_trials_done` bigint DEFAULT '0',
  `vat` float NOT NULL DEFAULT '0',
  `servicelastrun` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `initialbalance` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `invoiceday` int DEFAULT '1',
  `autorefill` int DEFAULT '0',
  `loginkey` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `mac_addr` char(17) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '00-00-00-00-00-00',
  `id_timezone` char(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '0',
  `tag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `voicemail_permitted` int NOT NULL DEFAULT '0',
  `voicemail_activated` smallint NOT NULL DEFAULT '0',
  `last_notification` timestamp NULL DEFAULT NULL,
  `last_sms` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `email_notification` varchar(70) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `notify_email` smallint NOT NULL DEFAULT '0',
  `speech2mail` varchar(70) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `send_text` int DEFAULT '0',
  `send_sound` int DEFAULT '0',
  `credit_notification` int NOT NULL DEFAULT '-1',
  `id_group` int NOT NULL DEFAULT '1',
  `dillergroups` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `company_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `company_website` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `vat_rn` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `traffic` bigint DEFAULT NULL,
  `traffic_target` varchar(300) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `discount` decimal(5,2) NOT NULL DEFAULT '0.00',
  `restriction` tinyint NOT NULL DEFAULT '0',
  `id_seria` int DEFAULT NULL,
  `serial` bigint DEFAULT NULL,
  `block` tinyint NOT NULL DEFAULT '0',
  `lock_pin` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `lock_date` timestamp NULL DEFAULT NULL,
  `monitor` int DEFAULT '0',
  `recalldays` int NOT NULL DEFAULT '10',
  `recalltime` int NOT NULL DEFAULT '7200',
  `cbtimeoutunavailable` int NOT NULL DEFAULT '5',
  `cbattemptunavailable` int NOT NULL DEFAULT '20',
  `cbtimeoutbusy` int NOT NULL DEFAULT '20',
  `cbattemptbusy` int NOT NULL DEFAULT '3',
  `cbtimeoutnoanswer` int NOT NULL DEFAULT '10',
  `cbattemptnoanswer` int NOT NULL DEFAULT '3',
  `cbtimeoutmax` int NOT NULL DEFAULT '600',
  `paypal` int NOT NULL DEFAULT '0',
  `showcallstypedefault` int NOT NULL DEFAULT '0',
  `max_concurrent` int NOT NULL DEFAULT '10',
  PRIMARY KEY (`id`),
  UNIQUE KEY `cons_cc_card_username` (`username`),
  UNIQUE KEY `cons_cc_card_useralias` (`useralias`),
  KEY `creationdate` (`creationdate`),
  KEY `username` (`username`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_card_archive` (
  `id` bigint NOT NULL,
  `creationdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `firstusedate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
