  `chargea` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `timechargea` int NOT NULL DEFAULT '0',
  `billingblocka` int NOT NULL DEFAULT '0',
  `stepchargeb` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `chargeb` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `timechargeb` int NOT NULL DEFAULT '0',
  `billingblockb` int NOT NULL DEFAULT '0',
  `stepchargec` float NOT NULL DEFAULT '0',
  `chargec` float NOT NULL DEFAULT '0',
  `timechargec` int NOT NULL DEFAULT '0',
  `billingblockc` int NOT NULL DEFAULT '0',
  `startdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `stopdate` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `starttime` smallint unsigned DEFAULT '0',
  `endtime` smallint unsigned DEFAULT '10079',
  `id_trunk` int DEFAULT '-1',
  `ratecarddialprefix` char(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `out_of_intern_prefix_for_sure` int NOT NULL DEFAULT '0',
  `musiconhold` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `id_outbound_cidgroup` int DEFAULT '-1',
  `rounding_calltime` int NOT NULL DEFAULT '0',
  `rounding_threshold` int NOT NULL DEFAULT '0',
  `additional_block_charge` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `additional_block_charge_time` int NOT NULL DEFAULT '0',
  `tag` char(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `disconnectcharge_after` int NOT NULL DEFAULT '0',
  `is_merged` int DEFAULT '0',
  `additional_grace` int NOT NULL DEFAULT '0',
  `minimal_cost` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `announce_time_correction` decimal(5,3) NOT NULL DEFAULT '1.000',
  `destination` bigint DEFAULT '0',
  `length_range_from` int NOT NULL DEFAULT '1',
  `length_range_till` int NOT NULL DEFAULT '100',
  PRIMARY KEY (`id`),
  KEY `ind_cc_ratecard_dialprefix` (`dialprefix`),
  KEY `idtariffplan_index` (`idtariffplan`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_receipt` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_card` bigint NOT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `title` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `description` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `status` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_receipt_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_receipt` bigint NOT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `price` decimal(15,5) NOT NULL DEFAULT '0.00000',
  `description` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `id_ext` bigint DEFAULT NULL,
  `type_ext` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_recognize_spool` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `status` smallint NOT NULL DEFAULT '0',
  `id_cc_card` bigint NOT NULL,
  `mailaddr` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `audiofile` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `answeredtime` smallint NOT NULL,
  `languagecode` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `send_sound` smallint NOT NULL,
  `send_text` smallint NOT NULL,
  `save_sound` smallint NOT NULL,
  `src` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `destination` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
