) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_ringup` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tag` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `trunks` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
