) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;

CREATE TABLE `cc_ringup_list` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_ringup` int NOT NULL DEFAULT '0',
  `tonum` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `name` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `info` tinytext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin,
  `try` smallint NOT NULL DEFAULT '0',
