CREATE TABLE `cc_service` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `amount` float NOT NULL,
