INSERT INTO `cc_card_group` (`id`, `name`, `description`, `users_perms`, `id_agent`, `provisioning`) VALUES (1,'DEFAULT','This group is the default group used when you create a customer. It\'s forbidden to delete it because you need at least one group but you can edit it.',262142,NULL,NULL);
INSERT INTO `cc_config` (`id`, `config_title`, `config_key`, `config_value`, `config_description`, `config_valuetype`, `config_listvalues`, `config_group_title`) VALUES (1,'Card Number length','interval_len_cardnumber','10-15','Card Number length, You can define a Range e.g: 10-15.',0,'10-15,5-20,10-30','global'),(2,'Card Alias length','len_aliasnumber','15','Card Number Alias Length e.g: 15.',0,NULL,'global'),(3,'Voucher length','len_voucher','15','Voucher Number Length.',0,NULL,'global'),(4,'Base Currency','base_currency','usd','Base Currency to use for application.',0,NULL,'global'),(5,'Invoice Image','invoice_image','asterisk01.jpg','Image to Display on the Top of Invoice',0,NULL,'global'),(6,'Admin Email','admin_email','root@localhost','Web Administrator Email Address.',0,NULL,'global'),(7,'DID Billing Days to pay','didbilling_daytopay','5','Define the amount of days you want to give to the user before releasing its DIDs',0,NULL,'global'),(8,'Manager Host','manager_host','localhost','Manager Host Address',0,NULL,'global'),(9,'Manager User ID','manager_username','myasterisk','Manger Host User Name',0,NULL,'global'),(10,'Manager Password','manager_secret','mycode','Manager Host Password',0,NULL,'global'),(11,'Use SMTP Server','smtp_server','0','Define if you want to use an STMP server or Send Mail (value yes for server SMTP)',1,'yes,no','global'),(12,'SMTP Host','smtp_host','localhost','SMTP Hostname',0,NULL,'global'),(13,'SMTP UserName','smtp_username','','User Name to connect on the SMTP server',0,NULL,'global'),(14,'SMTP Password','smtp_password','','Password to connect on the SMTP server',0,NULL,'global'),(15,'Use Realtime','use_realtime','1','if Disabled, it will generate the config files and offer an option to reload asterisk after an update on the Voip settings',1,'yes,no','global'),(16,'Go To Customer','customer_ui_url','../../customer/index.php','Link to the customer account',0,NULL,'global'),(17,'Context Callback','context_callback','a2billing-callback','Contaxt to use in Callback',0,NULL,'callback'),(18,'Extension','extension','1000','Extension to call while callback.',0,NULL,'callback'),(19,'Wait before callback','sec_wait_before_callback','10','Seconds to wait before callback.',0,NULL,'callback'),(20,'Avoid Repeat Duration','sec_avoid_repeate','10','Number of seconds before the call-back can be re-initiated from the web page to prevent repeated and unwanted calls.',0,NULL,'callback'),(21,'Time out','timeout','20','if the callback doesnt succeed within the value below, then the call is deemed to have failed.',0,NULL,'callback'),(22,'Answer on Call','answer_call','1','if we want to manage the answer on the call. Disabling this for callback trigger numbers makes it ring not hang up.',1,'yes,no','callback'),(23,'No of Predictive Calls','nb_predictive_call','10','number of calls an agent will do when the call button is clicked.',0,NULL,'callback'),(24,'Delay for Availability','nb_day_wait_before_retry','1','Number of days to wait before the number becomes available to call again.',0,NULL,'callback'),(25,'PD Contect','context_preditctivedialer','a2billing-predictivedialer','The context to redirect the call for the predictive dialer.',0,NULL,'callback'),(26,'Max Time to call','predictivedialer_maxtime_tocall','5400','When a call is made we need to limit the call duration : amount in seconds.',0,NULL,'callback'),(27,'PD Caller ID','callerid','123456','Set the callerID for the predictive dialer and call-back.',0,NULL,'callback'),(28,'Callback CallPlan ID','all_callback_tariff','1','ID Call Plan to use when you use the all-callback mode, check the ID in the \"list Call Plan\" - WebUI.',0,NULL,'callback'),(29,'Server Group ID','id_server_group','1','Define the group of servers that are going to be used by the callback.',0,NULL,'callback'),(30,'Audio Intro','callback_audio_intro','prepaid-callback_intro','Audio intro message when the callback is initiate.',0,NULL,'callback'),(47,'WebPhone Server','webphoneserver','localhost','IP address or domain name of asterisk server that would be used by the web-phone.',0,NULL,'webcustomerui'),(50,'CallerID Limit','limit_callerid','5','The total number of callerIDs for CLI Recognition that can be add by the customer.',0,NULL,'webcustomerui'),(51,'Trunk Name','sip_iax_info_trunkname','call-labs','Trunk Name to show in sip/iax info.',0,NULL,'sip-iax-info'),(52,'Codecs Allowed','sip_iax_info_allowcodec','g729','Allowed Codec, ulaw, gsm, g729.',0,NULL,'sip-iax-info'),(53,'Host','sip_iax_info_host','call-labs.com','Host information.',0,NULL,'sip-iax-info'),(54,'IAX Parms','iax_additional_parameters','canreinvite = no','IAX Additional Parameters.',0,NULL,'sip-iax-info'),(55,'SIP Parms','sip_additional_parameters','trustrpid = yes | sendrpid = yes | canreinvite = no','SIP Additional Parameters.',0,NULL,'sip-iax-info'),(56,'Enable','enable','1','Enable/Disable.',1,'yes,no','epayment_method'),(57,'HTTP Server Customer','http_server','http://www.call-labs.com','Set the Server Address of Customer Website, It should be empty for productive Servers.',0,NULL,'epayment_method'),(58,'HTTPS Server Customer','https_server','https://www.call-labs.com','https://localhost - Enter here your Secure Customers Server Address, should not be empty for productive servers.',0,NULL,'epayment_method'),(59,'Server Customer IP/Domain','http_cookie_domain','26.63.165.200','Enter your Domain Name or IP Address for the Customers application, eg, 26.63.165.200.',0,NULL,'epayment_method'),(60,'Secure Server Customer IP/Domain','https_cookie_domain','26.63.165.200','Enter your Secure server Domain Name or IP Address for the Customers application, eg, 26.63.165.200.',0,NULL,'epayment_method'),(61,'Application Customer Path','http_cookie_path','/customer/','Enter the Physical path of your Customers Application on your server.',0,NULL,'epayment_method'),(62,'Secure Application Customer Path','https_cookie_path','/customer/','Enter the Physical path of your Customers Application on your Secure Server.',0,NULL,'epayment_method'),(63,'Application Customer Physical Path','dir_ws_http_catalog','/customer/','Enter the Physical path of your Customers Application on your server.',0,NULL,'epayment_method'),(64,'Secure Application Customer Physical Path','dir_ws_https_catalog','/customer/','Enter the Physical path of your Customers Application on your Secure server.',0,NULL,'epayment_method'),(65,'Enable SSL','enable_ssl','1','secure webserver for checkout procedure?',1,'yes,no','epayment_method'),(66,'HTTP Domain','http_domain','26.63.165.200','Http Address.',0,NULL,'epayment_method'),(67,'Directory Path','dir_ws_http','/customer/','Directory Path.',0,NULL,'epayment_method'),(68,'Payment Amount','purchase_amount','1:2:5:10:20','define the different amount of purchase that would be available - 5 amount maximum (5:10:15).',0,NULL,'epayment_method'),(69,'Item Name','item_name','Credit Purchase','Item name that would be display to the user when he will buy credit.',0,NULL,'epayment_method'),(70,'Currency Code','currency_code','USD','Currency for the Credit purchase, only one can be define here.',0,NULL,'epayment_method'),(71,'Paypal Payment URL','paypal_payment_url','https://www.paypal.com/cgi-bin/webscr','Define here the URL of paypal gateway the payment (to test with paypal sandbox).',0,NULL,'epayment_method'),(72,'Paypal Verify URL','paypal_verify_url','ssl://www.paypal.com','paypal transaction verification url.',0,NULL,'epayment_method'),(73,'Authorize.NET Payment URL','authorize_payment_url','https://secure.authorize.net/gateway/transact.dll','Define here the URL of Authorize gateway.',0,NULL,'epayment_method'),(74,'PayPal Store Name','store_name','Asterisk2Billing','paypal store name to show in the paypal site when customer will go to pay.',0,NULL,'epayment_method'),(75,'Transaction Key','transaction_key','asdf1212fasd121554sd4f5s45sdf','Transaction Key for security of Epayment Max length of 60 Characters.',0,NULL,'epayment_method'),(77,'Enable','enable_signup','1','Enable Signup Module.',1,'yes,no','signup'),(78,'Captcha Security','enable_captcha','1','enable Captcha on the signup module (value : YES or NO).',1,'yes,no','signup'),(79,'Credit','credit','0','amount of credit applied to a new user.',0,NULL,'signup'),(80,'CallPlan ID List','callplan_id_list','1,2','the list of id of call plans which will be shown in signup.',0,NULL,'signup'),(81,'Card Activation','activated','0','Specify whether the card is created as active or pending.',1,'yes,no','signup'),(82,'Access Type','simultaccess','0','Simultaneous or non concurrent access with the card - 0 = INDIVIDUAL ACCESS or 1 = SIMULTANEOUS ACCESS.',0,NULL,'signup'),(83,'Paid Type','typepaid','0','PREPAID CARD  =  0 - POSTPAY CARD  =  1.',0,NULL,'signup'),(84,'Credit Limit','creditlimit','0','Define credit limit, which is only used for a POSTPAY card.',0,NULL,'signup'),(85,'Run Service','runservice','0','Authorise the recurring service to apply on this card  -  Yes 1 - No 0.',0,NULL,'signup'),(86,'Enable Expire','enableexpire','0','Enable the expiry of the card  -  Yes 1 - No 0.',0,NULL,'signup'),(87,'Date Format','expirationdate','','Expiry Date format YYYY-MM-DD HH:MM:SS. For instance 2004-12-31 00:00:00',0,NULL,'signup'),(88,'Expire Limit','expiredays','0','The number of days after which the card will expire.',0,NULL,'signup'),(89,'Create SIP','sip_account','1','Create a sip account from signup ( default : yes ).',1,'yes,no','signup'),(90,'Create IAX','iax_account','1','Create an iax account from signup ( default : yes ).',1,'yes,no','signup'),(91,'Activate Card','activatedbyuser','0','active card after the new signup. if No, the Signup confirmation is needed and an email will be sent to the user with a link for activation (need to put the link into the Signup mail template).',1,'yes,no','signup'),(92,'Customer Interface URL','urlcustomerinterface','http://localhost/customer/','url of the customer interface to display after activation.',0,NULL,'signup'),(93,'Asterisk Reload','reload_asterisk_if_sipiax_created','0','Define if you want to reload Asterisk when a SIP / IAX Friend is created at signup time.',1,'yes,no','signup'),(94,'Backup Path','backup_path','/tmp','Path to store backup of database.',0,NULL,'backup'),(95,'GZIP Path','gzip_exe','/bin/gzip','Path for gzip.',0,NULL,'backup'),(96,'GunZip Path','gunzip_exe','/bin/gunzip','Path for gunzip .',0,NULL,'backup'),(97,'MySql Dump Path','mysqldump','/usr/bin/mysqldump','path for mysqldump.',0,NULL,'backup'),(98,'PGSql Dump Path','pg_dump','/usr/bin/pg_dump','path for pg_dump.',0,NULL,'backup'),(99,'MySql Path','mysql','/usr/bin/mysql','Path for MySql.',0,NULL,'backup'),(100,'PSql Path','psql','/usr/bin/psql','Path for PSql.',0,NULL,'backup'),(101,'SIP File Path','buddy_sip_file','/etc/asterisk/additional_a2billing_sip.conf','Path to store the asterisk configuration files SIP.',0,NULL,'webui'),(102,'IAX File Path','buddy_iax_file','/etc/asterisk/additional_a2billing_iax.conf','Path to store the asterisk configuration files IAX.',0,NULL,'webui'),(103,'API Security Key','api_security_key','Ae87v56zzl34v','API have a security key to validate the http request, the key has to be sent after applying md5, Valid characters are [a-z,A-Z,0-9].',0,NULL,'webui'),(104,'Authorized IP','api_ip_auth','127.0.0.1','API to restrict the IPs authorised to make a request, Define The the list of ips separated by \';\'.',0,NULL,'webui'),(105,'Admin Email','email_admin','root@localhost','Administative Email.',0,NULL,'webui'),(106,'MOH Directory','dir_store_mohmp3','/var/lib/asterisk/mohmp3','MOH (Music on Hold) base directory.',0,NULL,'webui'),(107,'MOH Classes','num_musiconhold_class','10','Number of MOH classes you have created in musiconhold.conf : acc_1, acc_2... acc_10 class	etc....',0,NULL,'webui'),(108,'Display Help','show_help','1','Display the help section inside the admin interface  (YES - NO).',1,'yes,no','webui'),(109,'Max File Upload Size','my_max_file_size_import','1024000','File Upload parameters, PLEASE CHECK ALSO THE VALUE IN YOUR PHP.INI THE LIMIT IS 2MG BY DEFAULT .',0,NULL,'webui'),(110,'Audio Directory Path','dir_store_audio','/var/lib/asterisk/sounds/a2billing','Not used yet, The goal is to upload files and use them in the IVR.',0,NULL,'webui'),(111,'Max Audio File Size','my_max_file_size_audio','3072000','upload maximum file size.',0,NULL,'webui'),(112,'Extensions Allowed','file_ext_allow','gsm, mp3, wav','File type extensions permitted to be uploaded such as \"gsm, mp3, wav\" (separated by ,).',0,NULL,'webui'),(113,'Muzic Files Allowed','file_ext_allow_musiconhold','mp3','File type extensions permitted to be uploaded for the musiconhold such as \"gsm, mp3, wav\" (separate by ,).',0,NULL,'webui'),(114,'Link Audio','link_audio_file','0','Enable link on the CDR viewer to the recordings. (YES - NO).',1,'yes,no','webui'),(115,'Monitor Path','monitor_path','/var/spool/asterisk/monitor','Path to link the recorded monitor files.',0,NULL,'webui'),(116,'Monitor Format','monitor_formatfile','gsm','FORMAT OF THE RECORDED MONITOR FILE.',0,NULL,'webui'),(119,'Currency','currency_choose','usd, eur, cad, hkd','Allow the customer to chose the most appropriate currency (\"all\" can be used).',0,NULL,'webui'),(120,'Card Export Fields','card_export_field_list','card.id, username, useralias, lastname, credit, tariff, activated, language, inuse, currency, sip_bu','Fields to export in csv format from cc_card table.',0,NULL,'webui'),(121,'Vouvher Export Fields','voucher_export_field_list','voucher, credit, tag, activated, usedcardnumber, usedate, currency','Field to export in csv format from cc_voucher table.',0,NULL,'webui'),(122,'Advance Mode','advanced_mode','0','Advanced mode - Display additional configuration options on the ratecard (progressive rates, musiconhold, ...).',1,'yes,no','webui'),(123,'SIP/IAX Delete','delete_fk_card','1','Delete the SIP/IAX Friend & callerid when a card is deleted.',1,'yes,no','webui'),(124,'Type','type','friend','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(125,'Allow','allow','ulaw,alaw,gsm,g729','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(126,'Context','context','a2billing','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(127,'Nat','nat','yes','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(128,'AMA Flag','amaflag','billing','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(129,'Qualify','qualify','no','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(130,'Host','host','dynamic','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(131,'DTMF Mode','dtmfmode','RFC2833','Refer to sip.conf & iax.conf documentation for the meaning of those parameters.',0,NULL,'peer_friend'),(132,'Alarm Log File','cront_alarm','/var/log/a2billing/cront_a2b_alarm.log','To disable application logging, remove/comment the log file name aside service.',0,NULL,'log-files'),(133,'Auto refill Log File','cront_autorefill','/var/log/a2billing/cront_a2b_autorefill.log','To disable application logging, remove/comment the log file name aside service.',0,NULL,'log-files'),(134,'Bactch Process Log File','cront_batch_process','/var/log/a2billing/cront_a2b_batch_process.log','To disable application logging, remove/comment the log file name aside service .',0,NULL,'log-files'),(135,'Archive Log File','cront_archive_data','/var/log/a2billing/cront_a2b_archive_data.log','To disable application logging, remove/comment the log file name aside service .',0,NULL,'log-files'),(136,'DID Billing Log File','cront_bill_diduse','/var/log/a2billing/cront_a2b_bill_diduse.log','To disable application logging, remove/comment the log file name aside service .',0,NULL,'log-files'),(137,'Subscription Fee Log File','cront_subscriptionfee','/var/log/a2billing/cront_a2b_subscription_fee.log','To disable application logging, remove/comment the log file name aside service.',0,NULL,'log-files');
INSERT INTO `cc_config` (`id`, `config_title`, `config_key`, `config_value`, `config_description`, `config_valuetype`, `config_listvalues`, `config_group_title`) VALUES (138,'Currency Cront Log File','cront_currency_update','/var/log/a2billing/cront_a2b_currency_update.log','To disable application logging, remove/comment the log file name aside service.',0,NULL,'log-files'),(139,'Invoice Cront Log File','cront_invoice','/var/log/a2billing/cront_a2b_invoice.log','To disable application logging, remove/comment the log file name aside service.',0,NULL,'log-files'),(140,'Cornt Log File','cront_check_account','/var/log/a2billing/cront_a2b_check_account.log','To disable application logging, remove/comment the log file name aside service .',0,NULL,'log-files'),(141,'Paypal Log File','paypal','/var/log/a2billing/a2billing_paypal.log','paypal log file, to log all the transaction & error.',0,NULL,'log-files'),(142,'EPayment Log File','epayment','/var/log/a2billing/a2billing_epayment.log','epayment log file, to log all the transaction & error .',0,NULL,'log-files'),(143,'ECommerce Log File','api_ecommerce','/var/log/a2billing/a2billing_api_ecommerce_request.log','Log file to store the ecommerce API requests .',0,NULL,'log-files'),(144,'Callback Log File','api_callback','/var/log/a2billing/a2billing_api_callback_request.log','Log file to store the CallBack API requests.',0,NULL,'log-files'),(145,'Webservice Card Log File','api_card','/var/log/a2billing/a2billing_api_card.log','Log file to store the Card Webservice Logs',0,NULL,'log-files'),(146,'AGI Log File','agi','/var/log/a2billing/a2billing_agi.log','File to log.',0,NULL,'log-files'),(147,'Description','description','agi-config','Description/notes field',0,NULL,'agi-conf1'),(148,'Asterisk Version','asterisk_version','1_4','Asterisk Version Information, 1_1, 1_2, 1_4, 1_6, 1_8, 1_12, 1_16',0,'1_1,1_2,1_4,1_6,1_8,1_12,1_16','agi-conf1'),(149,'Answer Call','answer_call','1','Manage the answer on the call. Disabling this for callback trigger numbers makes it ring not hang up.',1,'yes,no','agi-conf1'),(150,'Play Audio','play_audio','1','Play audio - this will disable all stream file but not the Get Data , for wholesale ensure that the authentication works and than number_try = 1.',1,'yes,no','agi-conf1'),(151,'Say GoodBye','say_goodbye','0','play the goodbye message when the user has finished.',1,'yes,no','agi-conf1'),(152,'Play Language Menu','play_menulanguage','0','enable the menu to choose the language, press 1 for English, pulsa 2 para el espaÃ±ol, Pressez 3 pour FranÃ§ais',1,'yes,no','agi-conf1'),(153,'Force Language','force_language','','force the use of a language, if you dont want to use it leave the option empty, Values : ES, EN, FR, etc... (according to the audio you have installed).',0,NULL,'agi-conf1'),(154,'Intro Prompt','intro_prompt','','Introduction prompt : to specify an additional prompt to play at the beginning of the application .',0,NULL,'agi-conf1'),(155,'Min Call Credit','min_credit_2call','0','Minimum amount of credit to use the application .',0,NULL,'agi-conf1'),(156,'Min Bill Duration','min_duration_2bill','0','this is the minimum duration in seconds of a call in order to be billed any call with a length less than min_duration_2bill will have a 0 cost useful not to charge callers for system errors when a call was answered but it actually didn\'t connect.',0,NULL,'agi-conf1'),(157,'Not Enough Credit','notenoughcredit_cardnumber','0','if user doesn\'t have enough credit to call a destination, prompt him to enter another cardnumber .',1,'yes,no','agi-conf1'),(158,'New Caller ID','notenoughcredit_assign_newcardnumber_cid','0','if notenoughcredit_cardnumber = YES  then	assign the CallerID to the new cardnumber.',1,'yes,no','agi-conf1'),(159,'Use DNID','use_dnid','0','if YES it will use the DNID and try to dial out, without asking for the phonenumber to call.',1,'yes,no','agi-conf1'),(160,'Not Use DNID','no_auth_dnid','2400,2300','list the dnid on which you want to avoid the use of the previous option \"use_dnid\" .',0,NULL,'agi-conf1'),(161,'Try Count','number_try','3','number of times the user can dial different number.',0,NULL,'agi-conf1'),(162,'Force CallPlan','force_callplan_id','','this will force to select a specific call plan by the Rate Engine.',0,NULL,'agi-conf1'),(163,'Say Balance After Auth','say_balance_after_auth','1','Play the balance to the user after the authentication (values : yes - no).',1,'yes,no','agi-conf1'),(164,'Say Balance After Call','say_balance_after_call','0','Play the balance to the user after the call (values : yes - no).',1,'yes,no','agi-conf1'),(165,'Say Rate','say_rateinitial','0','Play the initial cost of the route (values : yes - no)',1,'yes,no','agi-conf1'),(166,'Say Duration','say_timetocall','1','Play the amount of time that the user can call (values : yes - no).',1,'yes,no','agi-conf1'),(167,'Auto Set CLID','auto_setcallerid','1','enable the setup of the callerID number before the outbound is made, by default the user callerID value will be use.',1,'yes,no','agi-conf1'),(168,'Force CLID','force_callerid','','If auto_setcallerid is enabled, the value of force_callerid will be set as CallerID.',0,NULL,'agi-conf1'),(169,'CLID Sanitize','cid_sanitize','0','If force_callerid is not set, then the following option ensures that CID is set to one of the card\'s configured caller IDs or blank if none available.(NO - disable this feature, caller ID can be anything, CID - Caller ID must be one of the customers caller IDs, DID - Caller ID must be one of the customers DID nos, BOTH - Caller ID must be one of the above two items)',0,NULL,'agi-conf1'),(170,'CLID Enable','cid_enable','0','enable the callerid authentication if this option is active the CC system will check the CID of caller  .',1,'yes,no','agi-conf1'),(171,'Ask PIN','cid_askpincode_ifnot_callerid','1','if the CID does not exist, then the caller will be prompt to enter his cardnumber .',1,'yes,no','agi-conf1'),(172,'FailOver LCR/LCD Prefix','failover_lc_prefix','0','if we will failover for LCR/LCD prefix. For instance if you have 346 and 34 for if 346 fail it will try to outbound with 34 route.',1,'yes,no','agi-conf1'),(173,'Auto CLID','cid_auto_assign_card_to_cid','1','if the callerID authentication is enable and the authentication fails then the user will be prompt to enter his cardnumber;this option will bound the cardnumber entered to the current callerID so that next call will be directly authenticate.',1,'yes,no','agi-conf1'),(180,'Auto CLID Security','callerid_authentication_over_cardnumber','0','to check callerID over the cardnumber authentication (to guard against spoofing).',1,'yes,no','agi-conf1'),(181,'SIP Call','sip_iax_friends','0','enable the option to call sip/iax friend for free (values : YES - NO).',1,'yes,no','agi-conf1'),(182,'SIP Call Prefix','sip_iax_pstn_direct_call_prefix','555','if SIP_IAX_FRIENDS is active, you can define a prefix for the dialed digits to call a pstn number .',0,NULL,'agi-conf1'),(183,'Direct Call','sip_iax_pstn_direct_call','0','this will enable a prompt to enter your destination number. if number start by sip_iax_pstn_direct_call_prefix we do directly a sip iax call, if not we do a normal call.',1,'yes,no','agi-conf1'),(184,'IVR Voucher Refill','ivr_voucher','0','enable the option to refill card with voucher in IVR (values : YES - NO) .',1,'yes,no','agi-conf1'),(185,'IVR Voucher Prefix','ivr_voucher_prefix','8','if ivr_voucher is active, you can define a prefix for the voucher number to refill your card, values : number - don\'t forget to change prepaid-refill_card_with_voucher audio accordingly .',0,NULL,'agi-conf1'),(186,'IVR Low Credit','jump_voucher_if_min_credit','0','When the user credit are below the minimum credit to call min_credit jump directly to the voucher IVR menu  (values: YES - NO) .',1,'yes,no','agi-conf1'),(187,'Dial Command Params','dialcommand_param','|60|HRrL(%timeout%:61000:30000)','More information about the Dial : http://voip-info.org/wiki-Asterisk+cmd+dial<br>30 :  The timeout parameter is optional. If not specifed, the Dial command will wait indefinitely, exiting only when the originating channel hangs up, or all the dialed channels return a busy or error condition. Otherwise it specifies a maximum time, in seconds, that the Dial command is to wait for a channel to answer.<br>H: Allow the caller to hang up by dialing * <br>r: Generate a ringing tone for the calling part',0,NULL,'agi-conf1'),(188,'SIP/IAX Dial Command Params','dialcommand_param_sipiax_friend','|60|HiL(3600000:61000:30000)','by default (3600000  =  1HOUR MAX CALL).',0,NULL,'agi-conf1'),(189,'Outbound Call','switchdialcommand','0','Define the order to make the outbound call<br>YES -> SIP/dialedphonenumber@gateway_ip - NO  SIP/gateway_ip/dialedphonenumber<br>Both should work exactly the same but i experimented one case when gateway was supporting dialedphonenumber@gateway_ip, So in case of trouble, try it out.',1,'yes,no','agi-conf1'),(190,'Failover Retry Limit','failover_recursive_limit','2','failover recursive search - define how many time we want to authorize the research of the failover trunk when a call fails (value : 0 - 20) .',0,NULL,'agi-conf1'),(191,'Max Time','maxtime_tocall_negatif_free_route','5400','This setting specifies an upper limit for the duration of a call to a destination for which the selling rate is less than or equal to 0.',0,NULL,'agi-conf1'),(192,'Send Reminder','send_reminder','0','Send a reminder email to the user when they are under min_credit_2call.',1,'yes,no','agi-conf1'),(193,'Record Call','record_call','0','enable to monitor the call (to record all the conversations) value : YES - NO .',1,'yes,no','agi-conf1'),(194,'Monitor File Format','monitor_formatfile','gsm','format of the recorded monitor file.',0,NULL,'agi-conf1'),(195,'AGI Force Currency','agi_force_currency','','Force to play the balance to the caller in a predefined currency, to use the currency set for by the customer leave this field empty.',0,NULL,'agi-conf1'),(196,'Currency Associated','currency_association','usd:dollars,mxn:pesos,eur:euros,all:credit','Define all the audio (without file extensions) that you want to play according to currency (use , to separate, ie \"usd:prepaid-dollar,mxn:pesos,eur:Euro,all:credit\").',0,NULL,'agi-conf1'),(198,'File Enter Destination','file_conf_enter_destination','prepaid-enter-dest','Please enter the file name you want to play when we prompt the calling party to enter the destination number, file_conf_enter_destination = prepaid-enter-number-u-calling-1-or-011.',0,NULL,'agi-conf1'),(200,'Bill Callback','callback_bill_1stleg_ifcall_notconnected','1','Define if you want to bill the 1st leg on callback even if the call is not connected to the destination.',1,'yes,no','agi-conf1'),(201,'International prefixes','international_prefixes','011,00,09,1','List the prefixes you want stripped off if the call plan requires it',0,NULL,'agi-conf1'),(202,'Server GMT','server_GMT','GMT+10:00','Define the sever gmt time',0,NULL,'global'),(203,'Invoice Template Path','invoice_template_path','../invoice/','gives invoice template path from default one',0,NULL,'global'),(204,'Outstanding Template Path','outstanding_template_path','../outstanding/','gives outstanding template path from default one',0,NULL,'global'),(205,'Sales Template Path','sales_template_path','../sales/','gives sales template path from default one',0,NULL,'global'),(206,'Extra charge DIDs','extracharge_did','1800,1900','Add extra per-minute charges to this comma-separated list of DNIDs; needs \"extracharge_fee\" and \"extracharge_buyfee\"',0,NULL,'agi-conf1'),(207,'Extra charge DID fees','extracharge_fee','0,0','Comma-separated list of extra sell-rate charges corresponding to the DIDs in \"extracharge_did\" - ie : 0.08,0.18',0,NULL,'agi-conf1'),(208,'Extra charge DID buy fees','extracharge_buyfee','0,0','Comma-separated list of extra buy-rate charges corresponding to the DIDs in \"extracharge_did\" - ie : 0.04,0.13',0,NULL,'agi-conf1'),(210,'List of possible values to notify','values_notifications','10:20:50:100:500:1000','Possible values to choose when the user receive a notification. You can define a List e.g: 10:20:100.',0,NULL,'notifications'),(211,'Notifications Modules','notification','1','Enable or Disable the module of notification for the customers',1,'yes,no','webcustomerui'),(212,'Notications Cron Module','cron_notifications','1','Enable or Disable the cron module of notification for the customers. If it correctly configured in the crontab',0,'yes,no','notifications'),(213,'Notications Delay','delay_notifications','1','Delay in number of days to send an other notification for the customers. If the value is 0, it will notify the user everytime the cront is running.',0,NULL,'notifications'),(214,'Payment Amount','purchase_amount_agent','100:200:500:1000','define the different amount of purchase that would be available.',0,NULL,'epayment_method'),(215,'Max Time For Unlimited Calls','maxtime_tounlimited_calls','5400','For unlimited calls, limit the duration: amount in seconds .',0,NULL,'agi-conf1'),(216,'Max Time For Free Calls','maxtime_tofree_calls','5400','For free calls, limit the duration: amount in seconds .',0,NULL,'agi-conf1'),(217,'CallPlan threshold Deck switch','callplan_deck_minute_threshold','','CallPlan threshold Deck switch. <br/>This option will switch the user callplan from one call plan ID to and other Callplan ID\nThe parameters are as follow : <br/>\n-- ID of the first callplan : called seconds needed to switch to the next CallplanID <br/>\n-- ID of the second callplan : called seconds needed to switch to the next CallplanID <br/>\n-- if not needed seconds are defined it will automatically switch to the next one <br/>\n-- if defined we will sum the previous needed seconds and check if',0,NULL,'agi-conf1'),(219,'Menu Language Order','conf_order_menulang','en:fr:es','Enter the list of languages authorized for the menu.Use the code language separate by a colon charactere e.g: en:es:fr',0,NULL,'agi-conf1'),(220,'Disable annoucement the second of the times that the card can call','disable_announcement_seconds','0','Desactived the annoucement of the seconds when there are more of one minutes (values : yes - no)',1,'yes,no','agi-conf1'),(221,'Charge for the paypal extra fees','charge_paypal_fee','0','Actived, if you want assum the fee of paypal and don\'t apply it on the customer (values : yes - no)',1,'yes,no','epayment_method'),(223,'Context Campaign\'s Callback','context_campaign_callback','a2billing-campaign-callback','Context to use in Campaign of Callback',0,NULL,'callback'),(224,'Default Context forward Campaign\'s Callback ','default_context_campaign','campaign','Context to use by default to forward the call in Campaign of Callback',0,NULL,'callback'),(225,'Card Show Fields','card_show_field_list','id:,username:, useralias:, lastname:,id_group:, id_agent:,  credit:, tariff:, status:, language:, in','Fields to show in Customer. Order is important. You can setup size of field using \"fieldname:10%\" notation or \"fieldname:\" for harcoded size,\"fieldname\" for autosize. <br/>You can use:<br/> id,username, useralias, lastname, id_group, id_agent,  credit, tariff, status, language, inuse, currency, sip_buddy, iax_buddy, nbused, firstname, email, discount, callerid, id_seria, serial',0,NULL,'webui'),(226,'Enable CDR local cache','cache_enabled','0','If you want enabled the local cache to save the CDR in a SQLite Database.',1,'yes,no','global'),(227,'Path for the CDR cache file','cache_path','/etc/asterisk/cache_a2billing','Defined the file that you want use for the CDR cache to save the CDR in a local SQLite database.',0,NULL,'global'),(228,'PNL Pay Phones','report_pnl_pay_phones','(8887798764,0.02,0.06)','Info for PNL report. Must be in form \"(number1,buycost,sellcost),(number2,buycost,sellcost)\", number can be prefix, i.e 1800',0,NULL,'webui'),(229,'PNL Toll Free Numbers','report_pnl_toll_free','(6136864646,0.1,0),(6477249717,0.1,0)','Info for PNL report. must be in form \"(number1,buycost,sellcost),(number2,buycost,sellcost)\", number can be prefix, i.e 1800',0,NULL,'webui'),(230,'Verbosity','verbosity_level','0','0 = FATAL; 1 = ERROR; WARN = 2 ; INFO = 3 ; DEBUG = 4',0,NULL,'agi-conf1');
INSERT INTO `cc_config` (`id`, `config_title`, `config_key`, `config_value`, `config_description`, `config_valuetype`, `config_listvalues`, `config_group_title`) VALUES (231,'Logging','logging_level','3','0 = FATAL; 1 = ERROR; WARN = 2 ; INFO = 3 ; DEBUG = 4',0,NULL,'agi-conf1'),(232,'Enable info module about customers','customer_info_enabled','LEFT','If you want enabled the info module customer and place it somewhere on the home page.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(233,'Enable info module about refills','refill_info_enabled','CENTER','If you want enabled the info module refills and place it somewhere on the home page.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(234,'Enable info module about payments','payment_info_enabled','CENTER','If you want enabled the info module payments and place it somewhere on the home page.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(235,'Enable info module about calls','call_info_enabled','RIGHT','If you want enabled the info module calls and place it somewhere on the home page.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(236,'PlugnPay Payment URL','plugnpay_payment_url','https://pay1.plugnpay.com/payment/pnpremote.cgi','Define here the URL of PlugnPay gateway.',0,NULL,'epayment_method'),(237,'DIDX ID','didx_id','708XXX','DIDX parameter : ID',0,NULL,'webui'),(238,'DIDX PASS','didx_pass','XXXXXXXXXX','DIDX parameter : Password',0,NULL,'webui'),(239,'DIDX MIN RATING','didx_min_rating','0','DIDX parameter : min rating',0,NULL,'webui'),(240,'DIDX RING TO','didx_ring_to','0','DIDX parameter : ring to',0,NULL,'webui'),(241,'Card Serial Pad Length','card_serial_length','7','Value of zero padding for serial. If this value set to 3 serial wil looks like 001',0,NULL,'webui'),(242,'Dial Balance reservation','dial_balance_reservation','0.25','Credit to reserve from the balance when a call is made. This will prevent negative balance on huge peak.',0,NULL,'agi-conf1'),(243,'Rate Export Fields','rate_export_field_list','destination, dialprefix, rateinitial','Fields to export in csv format from rates table.Use dest_name from prefix name',0,NULL,'webui'),(244,'HTTP Server Agent','http_server_agent','http://www.call-labs.com','Set the Server Address of Agent Website, It should be empty for productive Servers.',0,NULL,'epayment_method'),(245,'HTTPS Server Agent','https_server_agent','https://www.call-labs.com','https://localhost - Enter here your Secure Agents Server Address, should not be empty for productive servers.',0,NULL,'epayment_method'),(246,'Server Agent IP/Domain','http_cookie_domain_agent','26.63.165.200','Enter your Domain Name or IP Address for the Agents application, eg, 26.63.165.200.',0,NULL,'epayment_method'),(247,'Secure Server Agent IP/Domain','https_cookie_domain_agent','26.63.165.200','Enter your Secure server Domain Name or IP Address for the Agents application, eg, 26.63.165.200.',0,NULL,'epayment_method'),(248,'Application Agent Path','http_cookie_path_agent','/agent/Public/','Enter the Physical path of your Agents Application on your server.',0,NULL,'epayment_method'),(249,'Secure Application Agent Path','https_cookie_path_agent','/agent/Public/','Enter the Physical path of your Agents Application on your Secure Server.',0,NULL,'epayment_method'),(250,'Application Agent Physical Path','dir_ws_http_catalog_agent','/agent/Public/','Enter the Physical path of your Agents Application on your server.',0,NULL,'epayment_method'),(251,'Secure Application Agent Physical Path','dir_ws_https_catalog_agent','/agent/Public/','Enter the Physical path of your Agents Application on your Secure server.',0,NULL,'epayment_method'),(252,'Personal Info','personalinfo','1','Enable or disable the page which allow agent to modify its personal information.',0,'yes,no','webagentui'),(253,'Return URL distant Login','return_url_distant_login','','URL for specific return if an error occur after login',0,NULL,'webcustomerui'),(254,'Return URL distant Forget Password','return_url_distant_forgetpassword','','URL for specific return if an error occur after forgetpassword',0,NULL,'webcustomerui'),(255,'SMTP Port','smtp_port','25','Port to connect on the SMTP server',0,NULL,'global'),(256,'SMTP Secure','smtp_secure','','sets the prefix to the SMTP server : tls ; ssl',0,NULL,'global'),(257,'Option CallerID update','callerid_update','0','Prompt the caller to update his callerID',1,'yes,no','agi-conf1'),(259,'Option Local Dialing','local_dialing_addcountryprefix','0','Add the countryprefix of the user in front of the dialed number if this one have only 1 leading zero',1,'yes,no','agi-conf1'),(260,'Call to free DID Dial Command Params','dialcommand_param_call_2did','|60|HiL(%timeout%:61000:30000)','%timeout% is the value of the paramater : \'Max time to Call a DID no billed\'',0,NULL,'agi-conf1'),(261,'Max time to Call a DID no billed','max_call_call_2_did','3600','max time to call a did of the system and not billed . this max value is in seconde and by default (3600 = 1HOUR MAX CALL).',0,NULL,'agi-conf1'),(262,'Auto Create Card','cid_auto_create_card','0','if the callerID is captured on a2billing, this option will create automatically a new card and add the callerID to it.',1,'yes,no','agi-conf1'),(263,'Auto Create Card Length','cid_auto_create_card_len','10','set the length of the card that will be auto create (ie, 10).',0,NULL,'agi-conf1'),(264,'Auto Create Card Type','cid_auto_create_card_typepaid','PREPAID','billing type of the new card( value : POSTPAID or PREPAID) .',0,NULL,'agi-conf1'),(265,'Auto Create Card Credit','cid_auto_create_card_credit','0','amount of credit of the new card.',0,NULL,'agi-conf1'),(266,'Auto Create Card Limit','cid_auto_create_card_credit_limit','0','if postpay, define the credit limit for the card.',0,NULL,'agi-conf1'),(267,'Auto Create Card TariffGroup','cid_auto_create_card_tariffgroup','1','the tariffgroup to use for the new card (this is the ID that you can find on the admin web interface) .',0,NULL,'agi-conf1'),(268,'Paypal Amount Subscription','paypal_subscription_amount','10','amount to billed each recurrence of payment ',0,NULL,'epayment_method'),(269,'Paypal Subscription Time period number','paypal_subscription_period_number','1','number of time periods between each recurrence',0,NULL,'epayment_method'),(270,'Paypal Subscription Time period','paypal_subscription_time_period','M','time period (D=days, W=weeks, M=months, Y=years)',0,NULL,'epayment_method'),(271,'Enable PayPal subscription','paypal_subscription_enabled','0','Enable Paypal subscription on the User home page, you need a Premier or Business account.',1,'yes,no','epayment_method'),(272,'Paypal Subscription account','paypal_subscription_account','','Your PayPal ID or an email address associated with your PayPal account. Email addresses must be confirmed and bound to a Premier or Business Verified Account.',0,NULL,'epayment_method'),(273,'Base Country','base_country','USA','Define the country code in 3 letters where you are located (ISO 3166-1 : \"USA\" for United States)',0,'','global'),(274,'Base Language','base_language','en','Define your language code in 2 letters (ISO 639 : \"en\" for English)',0,'','global'),(275,'Authorize Remittance Request','remittance_request','1','Enable or disable the link which allow agent to submit a remittance request',0,'yes,no','webagentui'),(276,'Asterisk Version Global','asterisk_version','1_4','Asterisk Version Information, 1_1, 1_2, 1_4, 1_6, 1_8, 1_12, 1_16',0,'1_1,1_2,1_4,1_6,1_8,1_12,1_16','global'),(277,'Archive Calls','archive_call_prior_x_month','24','A cront can be enabled in order to archive your CDRs, this setting allow to define prior which month it will archive',0,NULL,'backup'),(278,'Days to bill before month anniversary','subscription_bill_days_before_anniversary','3','Numbers of days to bill a subscription service before the month anniversary',0,NULL,'global'),(279,'Enable info module about system','system_info_enable','LEFT','Enabled this if you want to display the info module and place it somewhere on the Dashboard.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(280,'Enable news module','news_enabled','RIGHT','Enabled this if you want to display the news module and place it somewhere on the Dashboard.',0,'NONE,LEFT,CENTER,RIGHT','dashboard'),(281,'Busy Timeout','busy_timeout','1','Define the timeout in second when indicate the busy condition',0,NULL,'agi-conf1'),(282,'Callback Reduce Balance','callback_reduce_balance','1','Define the amount to reduce the balance on Callback in order to make sure that the B leg wont alter the account into a negative value.',0,NULL,'agi-conf1'),(283,'Language field','field_language','1','Enable The Language Field -  Yes 1 - No 0.',1,'yes,no','signup'),(284,'Currency field','field_currency','1','Enable The Currency Field - Yes 1 - No 0. ',1,'yes,no','signup'),(285,'Last Name Field','field_lastname','1','Enable The Last Name Field - Yes 1 - No 0. ',1,'yes,no','signup'),(286,'First Name Field','field_firstname','1','Enable The First Name Field - Yes 1 - No 0. ',1,'yes,no','signup'),(287,'Address Field','field_address','1','Enable The Address Field - Yes 1 - No 0. ',1,'yes,no','signup'),(288,'City Field','field_city','1','Enable The City Field - Yes 1 - No 0. ',1,'yes,no','signup'),(289,'State Field','field_state','1','Enable The State Field - Yes 1 - No 0. ',1,'yes,no','signup'),(290,'Country Field','field_country','1','Enable The Country Field - Yes 1 - No 0. ',1,'yes,no','signup'),(291,'Zipcode Field','field_zipcode','1','Enable The Zipcode Field - Yes 1 - No 0. ',1,'yes,no','signup'),(292,'Timezone Field','field_id_timezone','1','Enable The Timezone Field - Yes 1 - No 0. ',1,'yes,no','signup'),(293,'Phone Field','field_phone','1','Enable The Phone Field - Yes 1 - No 0. ',1,'yes,no','signup'),(294,'Fax Field','field_fax','1','Enable The Fax Field - Yes 1 - No 0. ',1,'yes,no','signup'),(295,'Company Name Field','field_company','1','Enable The Company Name Field - Yes 1 - No 0. ',1,'yes,no','signup'),(296,'Company Website Field','field_company_website','1','Enable The Company Website Field - Yes 1 - No 0. ',1,'yes,no','signup'),(297,'VAT Registration Number Field','field_VAT_RN','1','Enable The VAT Registration Number Field - Yes 1 - No 0. ',1,'yes,no','signup'),(298,'Traffic Field','field_traffic','1','Enable The Traffic Field - Yes 1 - No 0. ',1,'yes,no','signup'),(299,'Traffic Target Field','field_traffic_target','1','Enable The Traffic Target Field - Yes 1 - No 0. ',1,'yes,no','signup'),(300,'IVR Locking option','ivr_enable_locking_option','0','Enable the IVR which allow the users to lock their account with an extra lock code.',1,'yes,no','agi-conf1'),(301,'IVR Account Information','ivr_enable_account_information','0','Enable the IVR which allow the users to retrieve different information about their account.',1,'yes,no','agi-conf1'),(302,'IVR Speed Dial','ivr_enable_ivr_speeddial','0','Enable the IVR which allow the users add speed dial.',1,'yes,no','agi-conf1'),(303,'Play rate lower one','play_rate_cents_if_lower_one','0','Play the initial cost even if the cents are less than one. if cost is 0.075, we will play : 7 point 5 cents per minute. (values : yes - no)',0,'yes,no','agi-conf1'),(304,'Callback Beep for Destination ','callback_beep_to_enter_destination','0','Set to yes, this will disable the standard prompt to enter destination and play a beep instead',1,'yes,no','agi-conf1'),(305,'Callback CID Prompt Confirm PhoneNumber ','cid_prompt_callback_confirm_phonenumber','0','Set to yes, a menu will be play to let the user confirm his phone number',1,'yes,no','agi-conf1'),(306,'LCR Mode','lcr_mode','0','LCR Mode<br>0: Classic (Search the longer prefix of all ratecards, then LCR with all ratecards with this prefix)<br>1: Provider (LCR with the longer available prefix for every ratecard independently)<br>',0,'','agi-conf1'),(307,'Currency Cents Association','currency_cents_association','usd:prepaid-cents,eur:prepaid-cents,gbp:prepaid-pence,all:credit','Define all the audio (without file extensions) that you want to play according to currency for the cents (use , to separate, ie \"usd:prepaid-cents,eur:prepaid-cents,gbp:prepaid-pence,all:credit\").',0,'','agi-conf1'),(308,'Prefix required','prefix_required','0','Is the prefix required for international calls',1,'yes,no','agi-conf1'),(309,'Group_ID List','group_id_list','1','ID list of Customer Groups which will be listed by default.',0,NULL,'signup'),(310,'WaitUp Sorting','waitup_sorting','0','',1,'yes,no','webui'),(311,'Fax Path','fax_path','/var/spool/asterisk/fax','Path to link the stored fax files.',0,NULL,'webui'),(312,'Time Zone','date_timezone','0','Defines the default timezone used by the date functions, eg Europe/Kiev',0,NULL,'global'),(313,'Main Title','main_title','..:: A2Billing Portal ::..','HTML title Attribute',0,NULL,'webui'),(314,'Conversion MixMonitor to Monitor','monitor_conversion','0','Use Asterisk command Monitor instead MixMonitor to right sync in/out channels',1,'yes,no','webui'),(315,'Google Cloud Text-to-Speech API Key','google_tts_key','','Your API Key for Google Cloud Text-to-Speech',0,NULL,'global'),(316,'Google Cloud Credentials Path','google_cloud_credential','/etc/credentials.json','Path to Google Cloud credentials.json',0,NULL,'global'),(317,'Google Cloud Storage Bucket Name','google_storage_bucketname','wav_folder','Name of the Cloud Storage Bucket',0,NULL,'global'),(318,'Google Cloud Storage Bucket Location','bucket_location','eu','The location of the Cloud Storage Bucket. US - USA. EU - Europe. EUROPE-WEST3 - Frankfurt, ASIA - some regions of Asia. EUR4 - Finland and Niderlands. NAM4 - Iowa and South Carolina.',0,'us,eu,europe-west3,asia,eur4,nam4','global'),(319,'D7 Networks SMS API Token previous version','d7_api_token_v0','','D7Networks.com: Online SMS Gateway & Messaging Services',0,NULL,'global'),(320,'D7 Networks SMS API Token','d7_api_token','','D7Networks.com: Online SMS Gateway & Messaging Services',0,NULL,'global'),(321,'System startup time','startup_time','0','Numbers in seconds since 1970-01-01 (Unix epoch)',0,NULL,'global'),(322,'Web favicon path','shortcut_icon','images/ico/sipde-icon-32x32.ico','Path to the shortcut icon of your whole system',0,NULL,'global'),(323,'System logo path','logo_path','images/logo/sipde-transparent.png','Path to the Logo of your whole system',0,NULL,'global'),(324,'Cert file path','certfile','/etc/letsencrypt/live/my.domain/fullchain.pem','Tell Asterisk where your cert file is',0,NULL,'global'),(325,'Private key path','privatekey','/etc/letsencrypt/live/my.domain/privkey.pem','Tell Asterisk where your private key is',0,NULL,'global'),(326,'Authority certificate path','cafile','/etc/letsencrypt/live/my.domain/chain.pem','Path to certificate authority certificate',0,NULL,'global'),(327,'Enabling slidebar','slidebar','0','Show slidebar for commercial using',1,'yes,no','webcustomerui'),(328,'Google Analytics 4 ID','google_ga4_id','','GA4 measurement ID (e.g. G-XG19QQ243S). Leave empty to disable Google Analytics.',0,NULL,'webcustomerui'),(329,'Google AdSense client ID','google_adsense_client_id','','AdSense client ID (e.g. ca-pub-3831618686142206). Ads require this ID and the corresponding slot ID. Leave empty to disable AdSense.',0,NULL,'webcustomerui'),(330,'Google AdSense login slot ID','google_adsense_login_slot','','AdSense slot ID for the sign-in page sidebar (e.g. 9932511633). Requires google_adsense_client_id. Leave empty to hide this ad.',0,NULL,'webcustomerui'),(331,'Google AdSense sidebar slot ID','google_adsense_sidebar_slot','','AdSense slot ID for public page sidebars (e.g. 6683420397). Requires google_adsense_client_id. Leave empty to hide these ads.',0,NULL,'webcustomerui'),(332,'Google AdSense article slot ID','google_adsense_article_slot','','AdSense in-article slot ID, including the feedback page (e.g. 5295414584). Requires google_adsense_client_id. Leave empty to hide these ads.',0,NULL,'webcustomerui'),(333,'Google Programmable Search ID','google_cse_id','','Programmable Search Engine ID used as cx (e.g. 0440f90a85788865d). Leave empty to disable Google search.',0,NULL,'webcustomerui'),(334,'E-mail to contact us','mailto','support@my.domain','Customers support email address',0,NULL,'webcustomerui');
