INSERT INTO `cc_templatemail` (`id`, `id_language`, `mailtype`, `fromemail`, `fromname`, `subject`, `messagetext`, `messagehtml`) VALUES (1,'en','signup','info@mydomainname.com','COMPANY NAME','SIGNUP CONFIRMATION','\nThank you for registering with us\n\nPlease click on below link to activate your account.\n\nhttp://customer.mydomainname.com/activate.php?key=$loginkey$\n\nPlease make sure you active your account by making payment to us either by\ncredit card, wire transfer, money order, cheque, and western union money\ntransfer, money Gram, and Pay pal.\n\n\nKind regards,\nCall Labs\n',''),(2,'en','reminder','info@mydomainname.com','COMPANY NAME','Your COMPANY NAME account $cardnumber$ is low on credit ($currency$ $c','\n\nYour COMPANY NAME Account number $cardnumber$ is running low on credit.\n\nThere is currently only $creditcurrency$ $currency$ left on your account which is lower than the warning level defined ($credit_notification$)\n\n\nPlease top up your account ASAP to ensure continued service\n\nIf you no longer wish to receive these notifications or would like to change the balance amount at which these warnings are generated,\nplease connect on your myaccount panel and change the appropriate parameters\n\n\nyour account information :\nYour account number for VOIP authentication : $cardnumber$\n\nhttp://myaccount.mydomainname.com/\nYour account login : $login$\nYour account password : $password$\n\n\nThanks,\n/COMPANY NAME Team\n-------------------------------------\nhttp://www.mydomainname.com\n ',''),(3,'en','forgetpassword','info@mydomainname.com','COMPANY NAME','Login Information','Your login information is as below:\n\nYour account is $cardnumber$\n\nYour password is $password$\n\nYour login is $login$\n\nhttp://mydomainname.com/A2BCustomer_UI/\n\nKind regards,\nCall Labs\n',''),(4,'en','signupconfirmed','info@mydomainname.com','COMPANY NAME','SIGNUP CONFIRMATION','Thank you for registering with us\n\nPlease make sure you active your account by making payment to us either by\ncredit card, wire transfer, money order, cheque, and western union money\ntransfer, money Gram, and Pay pal.\n\nYour account is $cardnumber$\n\nYour password is $password$\n\nTo go to your account :\nhttp://mydomainname.com/customer/\n\nKind regards,\nCall Labs\n',''),(5,'en','epaymentverify','info@mydomainname.com','COMPANY NAME','Epayment Gateway Security Verification Failed','Dear Administrator\n\nPlease check the Epayment Log, System has logged a Epayment Security failure. that may be a possible attack on epayment processing.\n\nTime of Transaction: $time$\nPayment Gateway: $paymentgateway$\nAmount: $itemAmount$\n\n\n\nKind regards,\nCall Labs\n',''),(6,'en','payment','info@mydomainname.com','COMPANY NAME','PAYMENT CONFIRMATION','Thank you for shopping at COMPANY NAME.\n\nShopping details is as below.\n\nItem Name = <b>$itemName$</b>\nItem ID = <b>$itemID$</b>\nAmount = <b>$itemAmount$</b>\nPayment Method = <b>$paymentMethod$</b>\nStatus = <b>$paymentStatus$</b>\n\n\nKind regards,\nCall Labs\n',''),(8,'en','did_paid','info@mydomainname.com','COMPANY NAME','DID notification - ($did$)','BALANCE REMAINING $balance_remaining$ $base_currency$\n\nAn automatic taking away of : $did_cost$ $base_currency$ has been carry out of your account to pay your DID ($did$)\n\nMonthly cost for DID : $did_cost$ $base_currency$\n\n',NULL),(9,'en','did_unpaid','info@mydomainname.com','COMPANY NAME','DID notification - ($did$)','BALANCE REMAINING $balance_remaining$ $base_currency$\n\nYour credit is not enough to pay your DID number ($did$), the monthly cost is : $did_cost$ $base_currency$\n\nYou have $days_remaining$ days to pay the invoice (REF: $invoice_ref$ ) or the DID will be automatically released \n\n',NULL),(10,'en','did_released','info@mydomainname.com','COMPANY NAME','DID released - ($did$)','The DID $did$ has been automatically released!\n\n',NULL),(11,'en','new_ticket','info@mydomainname.com','COMPANY NAME','Support Ticket #$ticket_id$','New Ticket Open (#$ticket_id$) From $ticket_owner$.\n Title : $ticket_title$\n Priority : $ticket_priority$ \n Status : $ticket_status$ \n Description : $ticket_description$ \n',NULL),(12,'en','modify_ticket','info@mydomainname.com','COMPANY NAME','Support Ticket #$ticket_id$','Ticket modified (#$ticket_id$) By $comment_creator$.\n Ticket Status -> $ticket_status$\n Description : $comment_description$ \n',NULL),(13,'en','invoice_to_pay','info@mydomainname.com','COMPANY NAME','Invoice to pay Ref: $invoice_reference$','New Invoice send with the reference : $invoice_reference$ .\n \n    Title : $invoice_title$ .\n Description : $invoice_description$\n \n    TOTAL (exclude VAT) : $invoice_total$  $base_currency$\n TOTAL (invclude VAT) : $invoice_total_vat$ $base_currency$ \n\n \n    TOTAL TO PAY : $invoice_total_vat$ $base_currency$\n\n \n    You can check and pay this invoice by your account on the web interface : http://mydomainname.com/customer/  ',NULL),(14,'en','subscription_paid','info@mydomainname.com','COMPANY NAME','Subscription notification - $subscription_label$ ($subscription_id$)','BALANCE  $credit$ $base_currency$\n\n\nA decrement of: $subscription_fee$ $base_currency$ has removed from your account to pay your service. ($subscription_label$)\n\n\nthe monthly cost is : $subscription_fee$\n\n',NULL),(15,'en','subscription_unpaid','info@mydomainname.com','COMPANY NAME','Subscription notification - $subscription_label$ ($subscription_id$)','BALANCE $credit$ $base_currency$\n\n\nYou do not have enough credit to pay your subscription,($subscription_label$), the monthly cost is : $subscription_fee$ $base_currency$\n\n\nYou have $days_remaining$ days to pay the invoice (REF: $invoice_ref$ ) or your service may cease \n\n',NULL),(16,'en','subscription_disable_card','info@mydomainname.com','COMPANY NAME','Service deactivated - unpaid service $subscription_label$ ($subscription_id$)','The account has been automatically deactivated until the invoice is settled.\n\n',NULL),(17,'en','fax_success','fax_robot@my.domain','Fax Robot','FAX received from $cid_number$','You have just received a $count$ page fax from $cid_number$ $cid_name$, at phone number $dest_exten$, on $datetime$.\r\nThe original fax document is attached in $format$ format.\r\n\r\nYou may also download copy of fax from your personal web page <a href=\"$urlcustomerinterface$/fax-history.php\">$urlcustomerinterface$/fax-history</a>\r\n\r\nKind regards,\r\nTeam <a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(18,'en','fax_failed','fax_robot@my.domain','Fax Robot','FAX receiving failed from $cid_number$','You have just received a fax attempt from $cid_number$ $cid_name$, at phone number $dest_exten$, on $datetime$.\r\nThere was a problem receiving the fax:  $fax_result$.\r\n\r\nYou may download copy of faxes from your personal web page <a href=\"$urlcustomerinterface$/fax-history.php\">$urlcustomerinterface$/fax-history</a>\r\n\r\nKind regards,\r\nTeam <a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(19,'ru','fax_success','fax_robot@my.domain','Fax Robot','Факс от $cid_number$','Получен факс из $count$ страниц/ы от $cid_number$ $cid_name$, на номер $dest_exten$.\r\n Время получения $datetime$.\r\nФакс в формате $format$ прикреплен к этому письму как обычный файл.\r\n\r\nВы так же можете загрузить копию этого факса с вашей персональной страницы <a href=\"$urlcustomerinterface$/fax-history\">кликнув на эту ссылку</a>.\r\n\r\nСпасибо за Ваш интерес к сервису <a href=\"http://www.my.domain/\">TEAM.LTD</a> !',NULL),(20,'ru','fax_failed','fax_robot@my.domain','Fax Robot','Попытка получения факса от $cid_number$','Факс от $cid_number$ $cid_name$ для $dest_exten$ не был получен по причине: $fax_result$.\r\n\r\nВы можете загружать копии полученных факсов с вашей персональной страницы <a href=\"$urlcustomerinterface$/fax-history\">кликнув на эту ссылку</a>.\r\nНастроить получение факсов можно в разделе МОЯ АТС => ФАКС МАШИНА.\r\n\r\nСпасибо за Ваш интерес к сервису <a href=\"http://www.my.domain/\">TEAM.LTD</a> !',NULL),(21,'ru','signup','info@my.domain','No Reply','АКТИВАЦИЯ УЧЁТНОЙ ЗАПИСИ','Спасибо за регистрацию в сервисе TEAM.LTD\r\n\r\nЧтобы активировать Вашу учётную запись кликните по ссылке:\r\n<a href=\"$urlcustomerinterface$/activate.php?key=$loginkey$\">$urlcustomerinterface$/activate.php?key=$loginkey$</a>\r\n\r\nЧтобы начать пользоваться сервисами пополните после активации балланс Вашего аккаунта с помощью кредитной карты, систем PayPal или WebMoney со <a href=\"https://customer.my.domain/checkout_payment.php?ui_language=russian\">страницы управления</a> Вашим аккаунтом.\r\n\r\n--\r\nС уважением.\r\nКоманда <a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(22,'ru','signupconfirmed','info@my.domain','No Reply','ПОДТВЕРЖДЕНИЕ РЕГИСТРАЦИИ','Благодарим за регистрацию!\r\n\r\nНачинайте экономить на связи уже сейчас и упрощайте свою жизнь с помощью нашего сервиса. Ведь теперь, Вы сам себе оператор!\r\n\r\nИнформация для доступа к управлению <u>Вашей учётной записью</u>:\r\nНомер учётной записи: $cardnumber$\r\nЛогин для входа: $login$\r\nПароль: $password$\r\nСсылка для входа: <a href=\"$urlcustomerinterface$/?ui_language=russian\">$urlcustomerinterface$</a>\r\n\r\nРекомендуется удалить данное письмо после прочтения.\r\n\r\n--\r\nСпасибо за ваш интерес к сервису <a href=\"http://www.my.domain/\">TEAM.LTD</a> !',NULL),(23,'ru','did_paid','info@my.domain','TEAM.LTD','DID уведомление - ($did$)','\r\nОСТАТОК НА БАЛАНСЕ ПОСЛЕ ОПЛАТЫ: $balance_remaining$ $base_currency$\r\n\r\nАвтоматически списано $did_cost$ $base_currency$ с Вашего счёта чтобы оплатить ежемесячный взнос за Ваш DID номер ($did$).\r\n\r\nЕжемесячный взнос за DID номер : $did_cost$ $base_currency$\r\n\r\n--\r\n<a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(24,'ru','did_unpaid','info@my.domain','TEAM.LTD','DID уведомление - ($did$)','\r\nОСТАТОК НА БАЛАНСЕ: $balance_remaining$ $base_currency$\r\n\r\nУ Вас не хватает средств чтобы оплатить Ваш DID номер ($did$), ежемесячный платёж составляет: $did_cost$ $base_currency$\r\n\r\nПроизведено резервирование номера на дополнительные $days_remaining$ дней чтобы Вы могли оплатить выставленный счёт (REF: $invoice_ref$). После истечения этого срока DID номер станет свободен для заказа в обычном порядке.\r\n\r\n--\r\n<a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(25,'ru','did_released','info@my.domain','TEAM.LTD','DID уведомление - ($did$)','\r\nУ Вас не хватило средств чтобы оплатить Ваш DID номер ($did$), ежемесячный платёж составлял: $did_cost$ $base_currency$\r\n\r\nDID номер $did$ был автоматически отключен и переведен в свободную продажу!\r\nВы можете заказать его вновь в обычном порядке.\r\n\r\n--\r\n<a href=\"http://www.my.domain/\">TEAM.LTD</a>',NULL),(26,'en','call_success','speech_robot@my.domain','Speech Robot','Call $cid_number$->$dest_exten$','<font face=\"Verdana\"><i>$text$</i></font>\r\n---------------------------------------------------------\r\nKind regards,\r\nTeam <a href=\"http://www.my.domain/\">IP Ltd</a>',NULL),(27,'ru','forgetpassword','info@my.domain','No Reply','Информация для входа','<font face=\"Verdana\">Это напоминание о персональной информации было отправлено\r\nавтоматически в ответ на Ваш запрос со страницы входа.\r\nРекомендуем хранить данное письмо в надёжном месте.\r\n\r\n<u>Информация для доступа к управлению Вашей учётной записью</u>:\r\n<i>Номер учётной записи</i>: $cardnumber$\r\n\r\n<i>Ссылка для входа</i>: <a href=\"$customerinterface$\">$customerinterface$</a>\r\n<i>Логин</i>: $login$\r\n<i>Пароль</i>: $password$\r\n<form name=\"form1\" method=\"post\" action=\"$customerinterface$userinfo.php\"><input type=\"hidden\" name=\"done\" value=\"submit_log\"><input type=\"hidden\" name=\"pr_login\" value=\"$login$\"><input type=\"hidden\" name=\"pr_password\" value=\"$password$\"><input name=\"\" type=\"submit\" value=\"ВОЙТИ\"/></form>\r\n\r\n--\r\nСпасибо за ваш интерес к сервису <a href=\"http://www.my.domain/\">TEAM.LTD</a> !</font>',NULL),(28,'en','smserror','info@my.domain','No Reply','SMS NOT SENT','<font face=\"Verdana\">SMS to $phoneto$ have not been sent.\r\n\r\n<b>ERROR DETAILS</b>\r\n\r\n$errors$\r\n\r\n--\r\nKind regards, Robot of <a href=\"http://www.my.domain/\">TEAM.LTD</a></font>',NULL);
